import Foundation
struct Pet: Encodable { let name: String }
let pet = Pet(name: "Bo")
let data = try JSONEncoder().encode(pet)
print(String(decoding: data, as: UTF8.self))

import Foundation
struct Pet: Decodable { let name: String }
let json = Data(#"{"name":"Bo"}"#.utf8)
let d = JSONDecoder()
let pet = try d.decode(Pet.self, from: json)
print(pet.name)

import Foundation
struct Row: Decodable { let userId: Int }
let j = Data(#"{"user_id":7}"#.utf8)
let d = JSONDecoder()
d.keyDecodingStrategy = .convertFromSnakeCase
print(try d.decode(Row.self, from: j).userId)

